<?php
namespace App\Domain\AI\Channels\WhatsApp\Services;use App\Domain\AI\Channels\WhatsApp\Models\{WhatsAppChannel,WhatsAppSession};use App\Domain\AI\Conversations\Enums\ConversationChannel;use App\Domain\AI\Conversations\Models\{Conversation,ConversationMessage};
final class DeliverWhatsAppHumanMessageService{public function __construct(private WhatsAppDeliveryService$deliveries,private ResolveWhatsAppChannelService$resolver){}public function deliver(Conversation$c,ConversationMessage$m):void{if($c->channel!==ConversationChannel::WhatsApp)return;$s=WhatsAppSession::where('conversation_id',$c->id)->firstOrFail();$stored=WhatsAppChannel::findOrFail($s->whatsapp_channel_id);$channel=$this->resolver->resolve($stored->webhook_key);if(!$s->insideWindow())throw new \DomainException('delivery_unavailable');$this->deliveries->text($channel,$s,$m);}}
